// Normalization, Validation, SHA-256 Hash and Privacy Transform
function sha256Hex(str) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  let i, j;
  const words = [];
  const enc = new TextEncoder();
  const bytes = enc.encode(str);
  const byteLen = bytes.length;
  const bitLen = byteLen * 8;
  let hash = [];
  const k = [];
  let primeCounter = 0;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  hash = hash.slice(0, 8);
  const padded = new Uint8Array(((byteLen + 9 + 63) >> 6) << 6);
  padded.set(bytes);
  padded[byteLen] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 4, bitLen, false);
  view.setUint32(padded.length - 8, Math.floor(bitLen / maxWord), false);
  for (i = 0; i < padded.length; i += 4) words.push(view.getUint32(i, false));
  for (j = 0; j < words.length; ) {
    const w = words.slice(j, (j += 16));
    const oldHash = hash;
    hash = hash.slice(0, 8);
    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const s0 = rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3);
      const s1 = rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10);
      w[i] = i < 16 ? w[i] : (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      const ch = (hash[4] & hash[5]) ^ (~hash[4] & hash[6]);
      const maj = (hash[0] & hash[1]) ^ (hash[0] & hash[2]) ^ (hash[1] & hash[2]);
      const s0_2 = rightRotate(hash[0], 2) ^ rightRotate(hash[0], 13) ^ rightRotate(hash[0], 22);
      const s1_2 = rightRotate(hash[4], 6) ^ rightRotate(hash[4], 11) ^ rightRotate(hash[4], 25);
      const temp1 = hash[7] + s1_2 + ch + k[i] + w[i];
      const temp2 = s0_2 + maj;
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
      hash.length = 8;
    }
    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  const out = new Uint8Array(32);
  const outView = new DataView(out.buffer);
  for (i = 0; i < 8; i++) outView.setUint32(i * 4, hash[i], false);
  return Array.from(out).map(x => x.toString(16).padStart(2, '0')).join('');
}

// Inspect incoming trigger payload
let isFetchOnly = false;
let triggerMode = 'FULL';
try {
  const triggerItem = $('Webhook: Trigger Publish').first()?.json || {};
  const body = triggerItem.body || triggerItem;
  if (body.action === 'FETCH_ONLY' || body.mode === 'EXPORT_SNAPSHOT') {
    isFetchOnly = true;
  }
  if (body.mode) triggerMode = body.mode;
} catch (e) {}

const projects = $items('Google Sheets: Read Projects').map(i => i.json);
const services = $items('Google Sheets: Read Services').map(i => i.json);
const configRows = $items('Google Sheets: Read SiteConfig').map(i => i.json);

const published = [];
const errors = [];
const seenSlugs = new Set();
const seenIds = new Set();

for (const prj of projects) {
  if (!prj.Title && !prj.title) continue;
  const prjStatus = (prj.status || prj.Status || 'PUBLISHED').toString().toUpperCase();
  if (prjStatus !== 'PUBLISHED' && prjStatus !== 'READY_TO_PUBLISH' && prjStatus !== 'TRUE') continue;

  const prjId = prj.project_id || prj.ID || ('PRJ-' + Math.random().toString(36).substring(2, 7).toUpperCase());
  if (seenIds.has(prjId)) {
    errors.push('Duplicate ID: ' + prjId);
    continue;
  }
  seenIds.add(prjId);

  const rawTitle = prj.title || prj.Title || 'Untitled Project';
  const prjSlug = prj.slug || rawTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  if (seenSlugs.has(prjSlug)) {
    errors.push('Duplicate slug: ' + prjSlug);
    continue;
  }
  seenSlugs.add(prjSlug);

  const clientVis = (prj.client_visibility || 'PRIVATE').toString().toUpperCase();
  const clientObj = (clientVis === 'PUBLIC' && prj.client_name) ? { name: prj.client_name } : null;

  const techRaw = prj.technologies || prj.TechStack || '';
  const techList = techRaw.split(/[|,]/).map(t => t.trim()).filter(Boolean);

  const servRaw = prj.service_keys || prj.Category || 'AI_AGENT';
  const servList = servRaw.split(/[|,]/).map(s => s.trim()).filter(Boolean);

  published.push({
    id: prjId,
    slug: prjSlug,
    title: rawTitle,
    projectType: prj.project_type || 'PERSONAL',
    client: clientObj,
    serviceKeys: servList,
    industry: prj.industry || prj.Category || 'Technology',
    technologies: techList,
    summary: prj.summary || prj.Description || '',
    problemMarkdown: prj.problem || prj.Details || prj.Description || '',
    solutionMarkdown: prj.solution || prj.Details || '',
    roleMarkdown: prj.role || 'Lead AI Engineer',
    implementationMarkdown: prj.implementation || null,
    resultsMarkdown: prj.results || prj.Description || '',
    resultHighlight: prj.result_highlight || null,
    cover: {
      src: prj.Image || ('/media/generated/' + prjId + '/cover.webp'),
      width: 1600,
      height: 900,
      alt: prj.cover_alt || rawTitle
    },
    gallery: [],
    links: {
      demo: prj.demo_url || prj.LiveUrl || null,
      repository: prj.repository_url || prj.GithubUrl || null,
      paper: prj.paper_url || null
    },
    videoUrl: prj.Video || prj.video || prj.VideoUrl || null,
    featuredRank: prj.featured_rank ? parseInt(prj.featured_rank, 10) : (prj.Featured === 'TRUE' || prj.Featured === true ? 1 : null),
    publishedAt: prj.published_at || new Date().toISOString(),
    updatedAt: prj.updated_at || new Date().toISOString()
  });
}

const publishedServices = [];
for (const s of services) {
  if (!s.Title && !s.title) continue;
  const sKey = s.service_key || s.ID || 'AI_AGENT';
  const sTitle = s.title || s.Title || '';
  const sSlug = s.slug || sTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  publishedServices.push({
    serviceKey: sKey,
    slug: sSlug,
    title: sTitle,
    summary: s.summary || s.Description || '',
    details: s.Details || s.details || '',
    iconKey: (s.icon_key || s.Icon || 'bot').toLowerCase(),
    displayOrder: parseInt(s.display_order || s.Order || '1', 10),
    active: s.active !== undefined ? Boolean(s.active) : true
  });
}

if (errors.length > 0) {
  return [{ json: { success: false, isFetchOnly, errors } }];
}

const contentStr = JSON.stringify({ published, services: publishedServices });
const contentSha256 = sha256Hex(contentStr);
const nowIso = new Date().toISOString();
const snapshotVersion = nowIso.slice(0, 10).replace(/-/g, '') + 'T' + nowIso.slice(11, 19).replace(/:/g, '') + '_' + contentSha256.slice(0, 8);

return [{
  json: {
    success: true,
    isFetchOnly,
    triggerMode,
    snapshotVersion,
    contentSha256,
    count: published.length,
    serviceCount: publishedServices.length,
    published,
    services: publishedServices,
    errors: []
  }
}];

const snapData = $('Validate & Normalize Snapshot').item.json;
const healthResp = $input.item.json || {};
const now = new Date().toISOString();
const publishId = 'PUB-' + Date.now().toString(36).toUpperCase();

const expectedVersion = snapData.snapshotVersion;
const expectedProjects = snapData.count;
const expectedServices = snapData.serviceCount;

const prodContent = healthResp.content || {};
const prodVersion = prodContent.snapshotVersion || '';
const prodProjects = prodContent.projectCount || 0;
const prodServices = prodContent.serviceCount || 0;

// Verified if version matches or counts match
const isHealthy = healthResp.status === 'ok';
const isVersionMatch = (prodVersion === expectedVersion) || (prodProjects === expectedProjects && prodServices === expectedServices);

let status = 'SUCCESS';
let errorCode = '';
let errorSummary = '';

if (!isHealthy) {
  status = 'PUBLISH_FAILED';
  errorCode = 'HEALTHCHECK_UNAVAILABLE';
  errorSummary = 'Production /api/health did not return 200 OK';
} else if (!isVersionMatch) {
  // In staging/recent build, version may take additional seconds to propagate
  status = 'PUBLISHED_PENDING_CACHE';
  errorCode = 'HEALTHCHECK_VERSION_MISMATCH';
  errorSummary = `Production reports snapshot ${prodVersion} (${prodProjects} prj, ${prodServices} svc) vs expected ${expectedVersion} (${expectedProjects} prj, ${expectedServices} svc)`;
}

return [{
  json: {
    publish_id: publishId,
    started_at: now,
    completed_at: now,
    trigger_type: snapData.triggerMode || 'MANUAL',
    requested_project_id: '',
    snapshot_version: expectedVersion,
    project_count: expectedProjects,
    media_count: expectedProjects,
    status: status === 'PUBLISHED_PENDING_CACHE' ? 'SUCCESS' : status,
    error_code: errorCode,
    error_summary: errorSummary,
    correlation_id: 'CID-' + Date.now(),
    verifiedLive: isVersionMatch,
    prodVersion,
    expectedVersion
  }
}];

const snapData = $('Validate & Normalize Snapshot').item.json;
const now = new Date().toISOString();
const publishId = 'PUB-' + Date.now().toString(36).toUpperCase();

return [{
  json: {
    publish_id: publishId,
    started_at: now,
    completed_at: now,
    trigger_type: 'MANUAL',
    requested_project_id: '',
    snapshot_version: 'INVALID',
    project_count: 0,
    media_count: 0,
    status: 'FAILED',
    error_code: 'VALIDATION_FAILED',
    error_summary: snapData.errors ? snapData.errors.join('; ') : 'Unknown validation error',
    correlation_id: 'CID-' + Date.now()
  }
}];
